let storageOK=true;
function readStore(key,fallback){try{const v=JSON.parse(localStorage.getItem('hc-functional-'+key));return v??fallback}catch{return fallback}}
const storedSaved=readStore('saved',[]);let saved=new Set((Array.isArray(storedSaved)?storedSaved:[]).filter(id=>deals.some(d=>d.id===id))), requests=readStore('requests',[]);if(!Array.isArray(requests))requests=[];requests=requests.filter(r=>r&&typeof r.id==='string'&&typeof r.subject==='string'&&['service','enquiry','mandate'].includes(r.kind));requests.forEach(r=>{if(!['In progress','Completed','Cancelled'].includes(r.status))r.status='In progress'});
const ui={page:'portfolio',cat:0,query:'',city:'',ticket:'',status:'',sort:'default',opView:'available',layout:'cards',visibleDeals:3,compare:new Set(),serviceQuery:'',requestFilter:'active',researchQuery:'',reportCity:'mumbai',portfolioTab:'overview'};
let wizard=null,toastTimer,lastFocus=null;
function persist(){try{localStorage.setItem('hc-functional-saved',JSON.stringify([...saved]));localStorage.setItem('hc-functional-requests',JSON.stringify(requests));storageOK=true}catch{storageOK=false;toast('Storage is unavailable. Download your draft before closing.')}}
function money(n){return n===null?'On request':n<1?'₹'+(n*100).toLocaleString('en-IN',{maximumFractionDigits:2})+' L':'₹'+n.toLocaleString('en-IN',{maximumFractionDigits:2})+' cr'}
function statusPill(s){return `<span class="status ${['Review','Limited'].includes(s)?'amber':s==='Open'?'':'neutral'}">${esc(s)}</span>`}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function openDialog(title,html,eyebrow=''){lastFocus=document.activeElement;$('#dialog-eyebrow').textContent=eyebrow;$('#modal-content').innerHTML=`<h2 id="dialog-title">${esc(title)}</h2>${html}`;$('#close-modal').innerHTML=icon('close');if(!$('#modal').open)$('#modal').showModal();$('#modal').scrollTop=0;}
function closeDialog(){if($('#modal').open)$('#modal').close();wizard=null;lastFocus?.focus?.()}
function getPage(){const hash=location.hash.slice(1).split('?')[0];if(!hash)return 'home';if(['home','opportunities','research','financing','portfolio','services'].includes(hash))return hash;const path=location.pathname.split('/').filter(Boolean);return ['portfolio','research','opportunities','financing','services'].find(p=>path.includes(p))||'portfolio'}
function nav(){const defs=[['home','Home','Home','grid'],['research','Research & Intelligence','Research','research'],['opportunities','Investment Opportunities','Investment Opportunities','grid'],['financing','Financing','Financing','capital'],['portfolio','My Portfolio','Portfolio','portfolio'],['services','Services','Services','services']];$('#navigation').innerHTML=defs.map(([id,full,short,i])=>`<a href="#${id}" class="${ui.page===id?'active':''}" ${ui.page===id?'aria-current="page"':''}>${icon(i)}<span class="full-label">${full}</span><span class="short-label">${short}</span></a>`).join('')}
function stat(label,value,note='',dark=false){return `<div class="stat ${dark?'dark':''}"><span class="stat-label">${icon(({Opportunities:'grid',Locations:'map',Saved:'bookmark','Enquiry drafts':'file','Asset value':'portfolio',Debt:'capital','Net equity':'chart','Gross annual rent':'income'})[label]||'chart')}${esc(label)}</span><strong class="stat-number">${esc(value)}</strong>${note?`<span class="stat-note">${esc(note)}</span>`:''}</div>`}
function pageHead(title,action=''){return `<div class="page-heading"><div><h1>${title}</h1></div><div class="actions">${action}</div></div>`}
function options(items,selected,first){return `${first!==undefined?`<option value="">${esc(first)}</option>`:''}${items.map(x=>{const [v,t]=Array.isArray(x)?x:[x,x];return `<option value="${esc(v)}" ${String(v)===String(selected)?'selected':''}>${esc(t)}</option>`}).join('')}`}
function filteredDeals(){let ds=deals.filter(d=>(ui.cat===-1||d.cat===ui.cat)&&(!ui.city||d.city===ui.city)&&(!ui.status||d.status===ui.status)&&(!ui.ticket||(d.ticket!==null&&d.ticket<=+ui.ticket))&&(ui.opView!=='saved'||saved.has(d.id))&&(!ui.query||[d.id,d.name,d.city,d.area,d.structure,categories[d.cat].name].join(' ').toLowerCase().includes(ui.query.toLowerCase())));return ds.sort((a,b)=>ui.sort==='ticket-asc'?(a.ticket??Infinity)-(b.ticket??Infinity):ui.sort==='ticket-desc'?(b.ticket??-Infinity)-(a.ticket??-Infinity):ui.sort==='name'?a.name.localeCompare(b.name):deals.indexOf(a)-deals.indexOf(b))}
function dealRow(d){return `<tr class="deal-row" data-record="${d.id}"><td class="deal-name"><div class="deal-name-top"><span class="deal-type-icon">${icon(categories[d.cat].icon)}</span><div><button data-detail="${d.id}">${esc(d.name)}</button><span class="deal-id">${d.id} · ${esc(d.structure)}</span></div></div><div class="mobile-location">${esc(d.city)} · ${esc(d.area)} &nbsp; ${statusPill(d.status)}</div></td><td class="deal-location">${esc(d.city)}<span class="cell-secondary">${esc(d.area)}</span></td><td><span class="cell-label">Minimum ticket</span><span class="cell-value">${money(d.ticket)}</span><span class="cell-secondary">${d.ticket===null?'By mandate':'Indicative'}</span></td><td><span class="cell-label">${esc(d.metricLabel)}</span><span class="cell-value">${esc(d.metricText)}</span><span class="cell-secondary mobile-hide">${esc(d.metricLabel)}</span></td><td class="deal-tenure"><span class="cell-label">${d.cat===3?'Lease remaining':d.cat===1?'Target delivery':'Indicative tenure'}</span><span class="cell-value">${d.tenureText}</span><span class="cell-secondary">${d.cat===3?'Lease remaining':d.cat===1?'Target delivery':'Indicative tenure'}</span></td><td class="deal-status">${statusPill(d.status)}</td><td class="deal-actions"><label class="compare-check"><input type="checkbox" data-compare="${d.id}" aria-label="Compare ${d.id}" ${ui.compare.has(d.id)?'checked':''}>Compare</label><button class="text-button" data-detail="${d.id}">View details</button><button class="icon-button ${saved.has(d.id)?'saved':''}" aria-label="${saved.has(d.id)?'Unsave':'Save'} ${d.id}" aria-pressed="${saved.has(d.id)}" data-save="${d.id}">${icon('bookmark')}</button></td></tr>`}
function dealCard(d){
 const termLabel=d.cat===3?'Lease remaining':d.cat===1?'Target delivery':'Indicative tenure';
 return `<article class="deal-entry" data-record="${d.id}" aria-labelledby="deal-title-${d.id}">
 <div class="deal-entry-heading"><span class="deal-symbol" aria-hidden="true">${icon(categories[d.cat].icon)}</span><div class="deal-entry-title"><div class="deal-entry-meta"><span>${categories[d.cat].short}</span><span>${d.id}</span></div><h2 id="deal-title-${d.id}"><button data-detail="${d.id}">${esc(d.name)}</button></h2><p>${esc(d.structure)}</p></div><button class="icon-button entry-save ${saved.has(d.id)?'saved':''}" aria-label="${saved.has(d.id)?'Unsave':'Save'} ${d.id}" aria-pressed="${saved.has(d.id)}" data-save="${d.id}">${icon('bookmark')}</button></div>
 <div class="deal-entry-metrics"><div><small>Minimum ticket</small><strong>${money(d.ticket)}</strong></div><div class="entry-key-metric"><small>${esc(d.metricLabel)}</small><strong>${esc(d.metricText)}</strong></div><div><small>${termLabel}</small><strong>${d.tenureText}</strong></div><div><small>${[1,2,3,4].includes(d.cat)?'Asset / allocation':'Issue / project size'}</small><strong>${esc(d.size)}</strong></div></div>
 <div class="deal-entry-footer"><div class="entry-status">${statusPill(d.status)}<span>${esc(d.city)}</span></div><div class="entry-actions"><label class="compare-check"><input type="checkbox" data-compare="${d.id}" aria-label="Compare ${d.id}" ${ui.compare.has(d.id)?'checked':''}>Compare</label><button class="btn light" data-detail="${d.id}">View details</button></div></div></article>`;
}
function opportunityPage(){
 const ds=filteredDeals(),shown=ds.slice(0,ui.visibleDeals),myRequests=requests.filter(r=>r.kind!=='service'&&r.status!=='Cancelled');
 return pageHead('Investment Opportunities',`<button class="btn light" data-action="mandate">${icon('plus')}<span>Submit<span class="desktop-label"> opportunity</span></span></button>`)+`
 <div class="opportunity-overview"><div><strong>${deals.length}</strong><span>opportunities</span></div><span class="overview-divider"></span><div><strong>${categories.length}</strong><span>categories</span></div><span class="overview-divider"></span><div><strong>${new Set(deals.map(d=>d.city)).size}</strong><span>cities</span></div><span class="overview-note">8 assets · 2 bonds</span></div>
 <div class="section-tabs" aria-label="Opportunity views">${[['available','Available',deals.length],['saved','Saved',saved.size],['enquiries','My enquiries',myRequests.length]].map(([v,t,n])=>`<button data-op-view="${v}" class="${ui.opView===v?'active':''}" aria-pressed="${ui.opView===v}">${t}<span class="count">${n}</span></button>`).join('')}</div>
 ${ui.opView==='enquiries'?requestList('opportunity'):`
 <div class="opportunity-categories" role="group" aria-label="Opportunity categories"><button class="category-choice ${ui.cat===-1?'active':''}" data-cat="-1" aria-pressed="${ui.cat===-1}">All <span>${deals.length}</span></button>${categories.map((c,i)=>`<button class="category-choice ${ui.cat===i?'active':''}" data-cat="${i}" aria-pressed="${ui.cat===i}" aria-label="${c.name}">${c.short}<span>${deals.filter(d=>d.cat===i).length}</span></button>`).join('')}</div>
 <div class="filter-workspace"><div class="table-toolbar"><div class="searchbox">${icon('search')}<input id="deal-search" type="search" aria-label="Search opportunities" placeholder="Search city, opportunity or ID" value="${esc(ui.query)}"></div><div class="desktop-filters"><select id="city-filter" aria-label="Filter location">${options(cityNames,ui.city,'All locations')}</select><select id="ticket-filter" aria-label="Maximum minimum ticket">${options([[1,'Up to ₹1 cr'],[5,'Up to ₹5 cr'],[10,'Up to ₹10 cr'],[25,'Up to ₹25 cr']],ui.ticket,'Any ticket size')}</select><select id="status-filter" aria-label="Filter status">${options(['Open','Limited','Review','Upcoming'],ui.status,'All statuses')}</select></div><button class="btn light filter-button" data-action="filters" aria-label="Open filters">${icon('filter')}<span>Filters${[ui.city,ui.ticket,ui.status].filter(Boolean).length?' ('+[ui.city,ui.ticket,ui.status].filter(Boolean).length+')':''}</span></button><button class="icon-button" data-action="export-deals" aria-label="Export all filtered opportunities CSV">${icon('download')}</button></div>${filterChips()}</div>
 <div class="result-bar"><span id="opportunity-count" role="status">${ds.length?`Showing <b>${shown.length}</b> of <b>${ds.length}</b>`:'0 opportunities'}</span><div class="result-controls"><select id="deal-sort" aria-label="Sort opportunities">${options([['default','Default order'],['ticket-asc','Ticket: low to high'],['ticket-desc','Ticket: high to low'],['name','Name: A to Z']],ui.sort)}</select><div class="layout-switch" aria-label="Opportunity layout"><button data-layout="cards" aria-pressed="${ui.layout==='cards'}" class="${ui.layout==='cards'?'active':''}" aria-label="Compact list view">${icon('file')}</button><button data-layout="table" aria-pressed="${ui.layout==='table'}" class="${ui.layout==='table'?'active':''}" aria-label="Table view">${icon('filter')}</button></div></div></div>
 ${ui.cat===5?'<div class="notice">Coupons are annual and are not yield to maturity.</div>':''}
 ${ds.length?`${ui.layout==='cards'?`<div class="opportunity-list" id="opportunity-results">${shown.map(dealCard).join('')}</div>`:`<div class="opportunity-table-wrap" id="opportunity-results"><table class="op-table"><thead><tr><th>Opportunity</th><th>Location</th><th>Min. ticket</th><th>Key metric</th><th>Term</th><th>Status</th><th>Compare / save</th></tr></thead><tbody>${shown.map(dealRow).join('')}</tbody></table></div>`}
 <div class="opportunity-pagination"><span>${shown.length} of ${ds.length} opportunities</span><div>${shown.length<ds.length?`<button class="btn light" data-action="show-more-deals" aria-controls="opportunity-results">Show ${Math.min(3,ds.length-shown.length)} more</button>`:''}${shown.length>3?'<button class="text-button" data-action="show-fewer-deals" aria-controls="opportunity-results">Show fewer</button>':''}</div></div>`:`<div class="empty">${icon('search')}<h3>${ui.opView==='saved'&&!saved.size?'No saved opportunities':'No matching opportunities'}</h3><p>${ui.opView==='saved'&&!saved.size?'Use the bookmark control on any opportunity.':'Try a different location, ticket size or search.'}</p><button class="btn light" data-action="reset-filters">Reset filters</button></div>`}
 <p class="section-footnote">Target IRR, rental yield, coupon and property prices use different bases. Returns are not assured.</p>`}`;
}
function filterChips(){const a=[];if(ui.city)a.push(['city',ui.city]);if(ui.ticket)a.push(['ticket','Ticket ≤ '+money(+ui.ticket)]);if(ui.status)a.push(['status',ui.status]);if(ui.query)a.push(['query','Search: '+ui.query]);return a.length?`<div class="filter-chips">${a.map(([k,v])=>`<button data-clear-filter="${k}" aria-label="Clear ${esc(v)}">${esc(v)} ×</button>`).join('')}<button data-action="reset-filters">Clear all</button></div>`:''}
function researchPage(){const q=ui.researchQuery.toLowerCase(),rs=resources.filter(r=>[r.title,r.provider,r.topic].join(' ').toLowerCase().includes(q)),rps=reports.filter(r=>[r.title,r.type].join(' ').toLowerCase().includes(q));return pageHead('Research & Intelligence')+`<div class="searchbox research-search">${icon('search')}<input id="research-search" type="search" value="${esc(ui.researchQuery)}" placeholder="Search research or platform" aria-label="Search research and platforms"></div><div class="split"><section><div class="section-title"><h2>Intelligence platforms</h2><span class="small">${rs.length} links</span></div><div class="panel link-list">${rs.map(r=>`<a class="research-link" href="${r.url}" target="_blank" rel="noopener noreferrer" aria-label="${r.title}: ${r.provider}, opens a new tab"><span class="resource-photo"><img src="assets/${['research4.jpg','research0.jpg','research2.jpg','research3.jpg','research7.jpg'][resources.indexOf(r)]}" alt="" loading="lazy"><span class="resource-icon">${icon(r.icon)}</span></span><div class="resource-copy"><h3>${r.title}</h3><p>${r.provider} · ${r.topic}</p><span class="resource-url">${new URL(r.url).hostname}</span></div><span class="link-type">Open</span></a>`).join('')||'<p class="small">No matching platform links.</p>'}</div><p class="section-footnote">Links open the provider’s public website in a new tab. Provider accounts or subscriptions may be required; these are not integrated Saarthi dashboards.</p></section><section><div class="section-title"><h2>Research reports</h2><span class="small">PDF</span></div><div class="panel report-list">${rps.map(r=>`<div class="report-row ${r.id==='annual'?'annual-report':''}"><img class="report-cover" src="assets/report-${r.id==='corridors'?'corridors':r.id}.png" alt="${esc(r.title)} report cover" loading="lazy"><div>${r.id==='annual'?'<span class="report-badge">ANNUAL RESEARCH</span>':''}<h3><a href="reports/${r.file}" target="_blank" rel="noopener">${r.title}</a></h3><span class="small">${r.type} · ${r.pages} pages</span></div><a href="reports/${r.file}" download class="btn light" aria-label="Download ${r.title}">${icon('download')}PDF</a></div>`).join('')||'<p class="small">No matching reports.</p>'}</div><div class="section-title"><h2>Location reports</h2><span class="small">PDF</span></div><div class="panel"><label for="report-city">Location</label><div class="location-controls"><select id="report-city">${options(cityNames.map(c=>[c.toLowerCase(),c]),ui.reportCity)}</select></div><div class="location-list">${[1,2,3,4].map(n=>`<a href="reports/location-${ui.reportCity}-0${n}.pdf" target="_blank" rel="noopener">${icon('file')}<span>${cityNames.find(c=>c.toLowerCase()===ui.reportCity)} · Location ${String(n).padStart(2,'0')}</span><span class="small">Open PDF</span></a>`).join('')}</div></div></section></div>`}
function servicesPage(){const q=ui.serviceQuery.toLowerCase();return pageHead('Services',`<button class="btn" data-action="new-service">${icon('plus')}New request</button>`)+`<div class="service-layout"><section><div class="searchbox">${icon('search')}<input id="service-search" type="search" placeholder="Find a service" value="${esc(ui.serviceQuery)}" aria-label="Search services"></div><div class="section-title"><h2>Service directory</h2><span class="small">${serviceGroups.reduce((sum, group) => sum + group[1].length, 0)} services</span></div>${serviceGroups.map(([title,items],i)=>{items=items.filter(n=>[n,title].join(' ').toLowerCase().includes(q));return items.length?`<details class="service-group" open><summary><span class="service-summary-image"><img src="assets/service${i}.jpg" alt="" loading="lazy"></span><span class="service-summary-text"><span class="service-group-number">0${i+1} / SERVICES</span>${title}</span><span class="count">${items.length}</span></summary>${items.map(n=>`<button class="service-row" data-service="${esc(n)}"><span>${esc(n)}</span><span>Request</span></button>`).join('')}</details>`:''}).join('')||'<div class="empty">No services match your search.</div>'}</section><section><div class="section-title" style="margin-top:0"><h2>My requests</h2><button class="text-button" data-action="export-services">${icon('download')}Export</button></div><p class="small">Download a request to share with your advisor.</p><div class="section-tabs" style="margin-top:12px">${[['active','Drafts'],['cancelled','Cancelled']].map(([id,label])=>`<button class="${ui.requestFilter===id?'active':''}" data-request-filter="${id}">${label}</button>`).join('')}</div>${requestList('service')}</section></div>`}
function requestList(kind){let list=requests.filter(r=>(kind==='service'?r.kind==='service':r.kind!=='service')&&(kind!=='service'||(ui.requestFilter==='cancelled'?r.status==='Cancelled':r.status!=='Cancelled'))).slice().reverse();return list.length?list.map(r=>`<article class="request-card"><div class="request-card-head"><div><span class="deal-id">${esc(r.id)}</span><h3>${esc(r.subject)}</h3><p>${esc(r.asset||r.deal||'')}${r.city?' · '+esc(r.city):''}</p></div>${statusPill(r.status)}</div><div class="request-foot"><span>${new Date(r.created).toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'})}</span><div class="request-tools"><button class="text-button" data-request="${esc(r.id)}">View request</button><button class="icon-button" data-download-request="${esc(r.id)}" aria-label="Download ${esc(r.id)}">${icon('download')}</button></div></div></article>`).join(''):`<div class="empty"><h3>${ui.requestFilter==='cancelled'&&kind==='service'?'No cancelled requests':'No requests yet'}</h3><p>${kind==='service'?'Choose a service to submit a request.':'Open an opportunity to save an enquiry, or submit your own opportunity.'}</p></div>`}
function portfolioPage(){const P=window.HCPortfolio;if(!P)return '<p>Loading portfolio…</p>';const pf=P.get(),assets=pf.assets,r=assets.length?P.calculate(assets):null;let content='';if(ui.portfolioTab==='risk')content=pf.report&&!pf.dirty?`<div class="pr" id="portfolio-output">${P.reportBody(pf.report)}</div>`:`<div class="empty"><h3>${pf.dirty?'Holdings have changed':'Generate a risk report'}</h3><p>Uses your current holdings. The six-lens methodology and stress tests are included.</p><button class="btn" data-action="generate-risk">Generate report</button></div>`;else if(ui.portfolioTab==='method')content=`<div class="pr panel">${P.methodology()}</div>`;else if(ui.portfolioTab==='holdings')content=`<div class="portfolio-tools"><label style="flex:1">Portfolio name<input id="portfolio-name" class="portfolio-name" value="${esc(pf.name)}" maxlength="120"></label><button class="btn light" data-action="add-holding">${icon('plus')}Add holding</button><button class="text-button" data-action="clear-portfolio">Clear portfolio</button></div>${holdings(assets)}`;else content=`<div class="summary-grid">${stat('Asset value',money(r?.total||0),assets.length+' holdings',true)}${stat('Debt',money(r?.debt||0),r?'LTV '+r.ltv.toFixed(1)+'%':'LTV —')}${stat('Net equity',money(r?.equity||0),'Asset value less debt')}${stat('Gross annual rent',money(r?.rent||0),r?'Yield '+(r.rent/r.total*100).toFixed(1)+'%':'Yield —')}</div>${r?`<div class="split portfolio-overview"><section class="panel"><h2>Allocation by city</h2>${r.geo.map(x=>`<div class="allocation-row"><div><span>${esc(x.name)}</span><b>${(x.value/r.total*100).toFixed(1)}%</b></div><div class="allocation-bar"><i style="width:${x.value/r.total*100}%"></i></div></div>`).join('')}<div class="section-title"><h3>Asset type</h3></div>${r.types.map(x=>`<div class="allocation-row"><div><span>${esc(x.name)}</span><b>${money(x.value)}</b></div><div class="allocation-bar"><i class="alt" style="width:${x.value/r.total*100}%"></i></div></div>`).join('')}</section><section class="panel"><h2>Review priorities</h2>${P.flags(r).slice(0,4).map(([critical,t,d])=>`<div class="review-line"><strong class="${critical?'danger-text':''}">${esc(t)}</strong><p>${esc(d)}</p></div>`).join('')}</section></div>`:''}<div class="section-title"><h2>Holdings</h2><button class="text-button" data-action="add-holding">${icon('plus')}Add holding</button></div>${holdings(assets)}`;return pageHead('My Portfolio',`<button class="btn" data-action="generate-risk">${icon('chart')}Risk report</button>`)+`<p class="small" style="margin:-8px 0 16px">${pf.sample?'Your portfolio':'Your working portfolio'} · Download a report to keep a copy.</p><div class="section-tabs scroll" aria-label="Portfolio views">${[['overview','Overview'],['holdings','Holdings'],['risk','Risk report'],['method','Methodology']].map(([id,label])=>`<button data-portfolio-tab="${id}" class="${ui.portfolioTab===id?'active':''}">${label}</button>`).join('')}</div>${content}`}
function holdings(assets){return assets.length?`<div class="holdings-grid">${assets.map((a,i)=>`<article class="holding-card"><div class="holding-head"><span class="holding-type-icon">${icon(a.type==='Land'?'land':a.type==='Residential'?'residential':'income')}</span><div><h3>${esc(a.name)}</h3><p>${esc(a.city)} · ${esc(a.type)} · ${esc(a.use)}</p></div><button class="icon-button" data-edit-holding="${i}" aria-label="Edit ${esc(a.name)}">${icon('edit')}</button></div><div class="holding-metrics"><div><small>Value</small><strong>${money(+a.value)}</strong></div><div><small>Debt</small><strong>${money(+a.debt)}</strong></div><div><small>Annual rent</small><strong>${money(+a.rent)}</strong></div></div><div class="holding-foot"><span>${esc(a.stage)}</span><span class="${a.docs==='Unresolved issue'?'danger-text':''}">${esc(a.docs)}</span></div></article>`).join('')}</div>`:`<div class="empty"><h3>No holdings</h3><p>Add your first property to begin.</p></div>`}
function selectCoInvestments(){
 const category = categories.findIndex(item => item.name === 'Co-investments');
 if (category >= 0) Object.assign(ui, {cat:category, query:'', opView:'available'});
}
function render(){const focus=document.activeElement,id=focus?.id,selection=focus&&['search','text'].includes(focus.type)?[focus.selectionStart,focus.selectionEnd]:null;
 const nextPage = getPage();
 if (nextPage === 'opportunities' && ui.page !== nextPage) selectCoInvestments();
 ui.page=nextPage;nav();if(ui.page==='home'){$('#app').innerHTML='';document.title='HC Saarthi | Home';return;}document.title='HC Saarthi | '+({opportunities:'Investment Opportunities',financing:'Financing',research:'Research & Intelligence',services:'Services',portfolio:'My Portfolio'}[ui.page]);$('#app').dataset.page=ui.page;$('#app').innerHTML=(!storageOK?'<div class="storage-error">Storage is unavailable. Download new drafts before closing.</div>':'')+({opportunities:opportunityPage,financing:financingPage,research:researchPage,services:servicesPage,portfolio:portfolioPage}[ui.page])();compareTray();if(id&&$('#'+id)){const e=$('#'+id);e.focus({preventScroll:true});if(selection)e.setSelectionRange(...selection)}}
window.portfolioRedraw=()=>{if(ui.page==='portfolio')render()};
function compareTray(){const tray=$('#compare-tray');tray.innerHTML=ui.compare.size&&ui.page==='opportunities'?`<span><b>${ui.compare.size} / 3</b> selected</span><button class="text-button" data-action="clear-compare">Clear</button><button class="btn" data-action="compare" ${ui.compare.size<2?'disabled':''}>Compare</button>`:''}
function detail(id){const d=deals.find(d=>d.id===id);if(!d)return;openDialog(d.name,`<p class="dialog-subtitle">${d.city} · ${d.area} &nbsp; ${statusPill(d.status)}</p><div class="detail-grid"><div><small>Minimum ticket</small><strong>${money(d.ticket)}</strong></div><div><small>${d.metricLabel}</small><strong>${d.metricText}</strong></div><div><small>${d.cat===3?'Lease remaining':d.cat===1?'Target delivery':'Indicative tenure'}</small><strong>${d.tenureText}</strong></div><div><small>${[1,2,3,4].includes(d.cat)?'Asset / allocation size':'Issue / project size'}</small><strong>${d.size}</strong></div></div><div class="detail-lines"><div class="detail-line"><span>Structure</span><span>${d.structure}</span></div><div class="detail-line"><span>${d.detailLabel}</span><span>${d.detailValue}</span></div><div class="detail-line"><span>Security / ownership</span><span>${d.security}</span></div></div><p class="small">${d.note}</p><div class="notice">Returns are not assured. Investments are subject to eligibility and definitive documentation.</div><div class="dialog-actions"><button class="btn" data-enquiry="${id}">Create enquiry</button><button class="btn light" data-brief="${id}">${icon('download')}Download brief</button></div><details style="margin-top:22px"><summary class="small" style="cursor:pointer">Representative image</summary><img class="dialog-image" src="assets/${d.image}" alt="Architecture"></details>`,id+' · '+categories[d.cat].name)}
function showComparison(){const ds=deals.filter(d=>ui.compare.has(d.id));const rows=[['Location',d=>d.city+' · '+d.area],['Structure',d=>d.structure],['Minimum ticket',d=>money(d.ticket)],['Key metric',d=>d.metricText+' — '+d.metricLabel],['Term',d=>d.tenureText+' — '+(d.cat===3?'lease remaining':d.cat===1?'target delivery':'indicative tenure')],['Size',d=>d.size],['Status',d=>d.status],['Security',d=>d.security]];openDialog('Compare opportunities',`<p class="dialog-subtitle">${ds.length} selected · Figures are indicative.</p><div class="comparison-wrap"><table class="comparison"><thead><tr><th>Terms</th>${ds.map(d=>`<th>${d.name}<small>${d.id}</small></th>`).join('')}</tr></thead><tbody>${rows.map(([k,f])=>`<tr><td>${k}</td>${ds.map(d=>`<td>${esc(f(d))}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="notice">Compare like-for-like measures. IRR, rental yield, coupons and asset prices are different measures and are not ranked together.</div>`,'COMPARISON')}
function filterDialog(){openDialog('Filter opportunities',`<form class="form" id="filter-form"><label>Location<select name="city">${options(cityNames,ui.city,'All locations')}</select></label><label>Maximum minimum ticket<select name="ticket">${options([[1,'Up to ₹1 cr'],[5,'Up to ₹5 cr'],[10,'Up to ₹10 cr'],[25,'Up to ₹25 cr']],ui.ticket,'Any ticket size')}</select><span class="form-note">Excludes “On request” when a limit is selected.</span></label><label>Status<select name="status">${options(['Open','Limited','Review','Upcoming'],ui.status,'All statuses')}</select></label><div class="dialog-actions"><button type="button" class="btn light" data-action="reset-modal-filters">Reset</button><button class="btn" type="submit">Apply filters</button></div></form>`,'OPPORTUNITIES')}
function enquiryForm(id){const d=deals.find(d=>d.id===id);openDialog('Create enquiry',`<p class="dialog-subtitle">${d.id} · ${d.name}</p><form class="form" id="enquiry-form" data-id="${id}"><label>Proposed amount (₹ crore)<input name="amount" type="number" min="${d.ticket??0.01}" step="0.01" required inputmode="decimal" value="${d.ticket??''}"><span class="form-note">${d.ticket?'Indicative minimum '+money(d.ticket):'Ticket size subject to mandate'}</span></label><label>Questions or requirements<textarea name="notes" maxlength="2000" placeholder="Optional"></textarea></label><p class="form-note">Your enquiry will appear in My Portfolio → Assets → My Services.</p><button class="btn" type="submit">Save enquiry draft</button></form>`,'DRAFT')}
function serviceForm(name=''){
 const all=serviceGroups.flatMap(g=>g[1]).sort((a,b)=>a.localeCompare(b));
 if (name && !all.includes(name) && Object.hasOwn(serviceSubtypes,name)) all.push(name);
 const current=all.includes(name)?name:'';
 const assets=window.CIOModel?.state?.assets||[];
 const subtype=serviceSubtypes[current]||[];
 openDialog('Submit a service request',`<form class="form e35-service-form" id="service-form"><label>Service<select name="service" id="e35-service-select" required>${options(all,current,'Choose a service')}</select></label><label>Type of assistance<select name="subtype" id="e35-service-subtype" required ${current?'':'disabled'}>${options(subtype,'','Select the type of assistance')}</select></label><label>Property / asset<input name="asset" list="e35-assets" maxlength="160" required placeholder="Choose or enter an asset name"><datalist id="e35-assets">${assets.map(a=>`<option value="${esc(a.name)}">`).join('')}</datalist></label><label>City<input name="city" maxlength="100" required placeholder="e.g. Mumbai"></label><label>Additional details <span class="e35-optional">Optional</span><textarea name="notes" maxlength="2000" placeholder="Add context if helpful; you can submit without a description."></textarea></label><div class="e35-form-callout"><span>Your request will be tracked in My Portfolio → Assets → My Services.</span></div><button type="submit" class="btn">Submit service request ↗</button></form>`,'');
}
function mandateForm(){openDialog('Submit an opportunity',`<form class="form" id="mandate-form"><label>Requirement<select name="mandate" required>${options(mandateOptions,'','Select requirement')}</select></label><label>Asset / opportunity name<input name="asset" required maxlength="160"></label><div class="form-row"><label>City<input name="city" required maxlength="100"></label><label>Value / capital need (₹ cr)<input name="amount" type="number" min="0.01" step="0.01" inputmode="decimal" placeholder="Optional"></label></div><label>Details<textarea name="notes" required maxlength="2000" placeholder="Location, size, ownership and requirement"></textarea></label><p class="form-note">Creates a mandate draft you can download.</p><button type="submit" class="btn">Save mandate draft</button></form>`,'CLIENT OPPORTUNITY')}
function addRequest(data){const id=(data.kind==='service'?'SR':data.kind==='mandate'?'MD':'EQ')+'-'+Date.now().toString(36).toUpperCase()+'-'+Math.random().toString(36).slice(2,5).toUpperCase();const r={...data,id,created:new Date().toISOString(),status:'In progress'};requests.push(r);persist();render();const service=data.kind==='service';openDialog(service?'Service request submitted':'Enquiry saved',`<div class="confirmation-icon">${icon('check')}</div><p>${service?'Your request is now tracked in My Portfolio and Services.':'Your enquiry is saved in My Portfolio → Assets → My Services.'}</p><div class="confirmation-details"><b>${esc(r.subject)}</b>${r.subtype?'<br>'+esc(r.subtype):''}<br>${esc(r.id)}<br>Status: ${esc(r.status)}</div><div class="dialog-actions"><button class="btn" data-download-request="${r.id}">${icon('download')}Download request</button><button class="btn light" data-action="close">Done</button></div>`,'REQUEST');}
function requestDetail(id){const r=requests.find(r=>r.id===id);if(!r)return;openDialog(r.subject,`<p class="dialog-subtitle">${r.id} · ${r.status}</p><div class="detail-lines">${[['Asset / opportunity',r.asset||r.deal],['City',r.city],...(r.subtype?[['Service subtype',r.subtype]]:[]),['Amount',r.amount?money(+r.amount):'Not specified'],...(r.kind==='service'&&window.SaarthiServiceProgress?[['Indicative progress',window.SaarthiServiceProgress(r).progress+'%'],['Estimated completion',window.SaarthiServiceProgress(r).eta]]:[]),['Created',new Date(r.created).toLocaleString('en-IN')]].map(([k,v])=>`<div class="detail-line"><span>${k}</span><span>${esc(v||'—')}</span></div>`).join('')}</div><form class="form" id="update-request-form" data-id="${r.id}"><label>Notes / requirements<textarea name="notes" maxlength="2000">${esc(r.notes)}</textarea></label>${r.status!=='Cancelled'?`<label>Status<select name="status">${options([['In progress','In progress'],['Completed','Completed']],r.status)}</select></label><p class="form-note">Updating this status does not notify or assign a service provider.</p>`:''}<div class="dialog-actions"><button class="btn" type="submit">Save changes</button><button type="button" class="btn light" data-download-request="${r.id}">${icon('download')}Download</button></div></form><button class="text-button ${r.status==='Cancelled'?'':'danger-text'}" style="margin-top:18px" data-toggle-request="${r.id}">${r.status==='Cancelled'?'Restore draft':'Cancel draft'}</button>`,'REQUEST DETAILS')}
function fileDownload(text,name,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000)}
function csvCell(v){let s=String(v??'');if(/^[=+@\-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}
function csv(rows,name){fileDownload('\uFEFF'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n'),name,'text/csv;charset=utf-8')}
function brief(id){const d=deals.find(d=>d.id===id);const rows=[['Opportunity ID',d.id],['Location',d.city+' / '+d.area],['Minimum ticket',money(d.ticket)],[d.metricLabel,d.metricText],['Term',d.tenureText],['Structure',d.structure],['Security / ownership',d.security],[d.detailLabel,d.detailValue],['Size',d.size],['Status',d.status]];const h=`<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(d.id)} — HC Saarthi</title><style>body{font:16px/1.6 Arial,sans-serif;max-width:800px;margin:40px auto;padding:20px;color:#17364d}h1{font-size:28px}table{width:100%;border-collapse:collapse}td{padding:12px;border-bottom:1px solid #dce5ec}td:first-child{color:#586e7d;width:40%}p{color:#586e7d}.note{padding:18px;background:#eef3f7}</style><p>HC SAARTHI · OPPORTUNITY BRIEF</p><h1>${esc(d.name)}</h1><table>${rows.map(([k,v])=>`<tr><td>${esc(k)}</td><td>${esc(v)}</td></tr>`).join('')}</table><p>${esc(d.note)}</p><p class="note">This is not an investment offer. Target returns are not assured. Coupon is not yield to maturity; gross yield excludes costs; IRR is a target.</p></html>`;fileDownload(h,'HC-Saarthi-'+id+'-Brief.html','text/html;charset=utf-8');toast('Brief downloaded')}
function downloadRequest(id){const r=requests.find(r=>r.id===id);if(!r)return;const t=['HC SAARTHI — REQUEST DRAFT','REQUEST SUMMARY','',...Object.entries(r).map(([k,v])=>k.toUpperCase()+': '+v),'','Generated from HC Saarthi.'].join('\n');fileDownload(t,'HC-Saarthi-'+id+'.txt','text/plain;charset=utf-8');toast('Draft downloaded')}
function startWizard(i=-1){wizard={i,step:0,asset:i<0?window.HCPortfolio.fresh():structuredClone(window.HCPortfolio.get().assets[i])};drawWizard()}
function formInput(label,key,type='text',extra=''){return `<label>${label}<input name="${key}" value="${esc(wizard.asset[key])}" type="${type}" ${extra}></label>`}
function wizardSelect(label,key,items){return `<label>${label}<select name="${key}">${options(items,wizard.asset[key])}</select></label>`}
function drawWizard(){const a=wizard.asset,s=wizard.step;const fields=s===0?`${formInput('Asset name','name','text','required maxlength="160"')}${formInput('City','city','text','required maxlength="100"')}<div class="form-row">${wizardSelect('Asset type','type',['Residential','Office','Retail','Logistics','Land','Hospitality','Other'])}${wizardSelect('Use','use',['Rental','Self-use','Development / land'])}</div>`:s===1?`<div class="form-row">${formInput('Estimated value (₹ cr)','value','number','min="0.01" step="0.01" required inputmode="decimal"')}${formInput('Debt (₹ cr)','debt','number','min="0" step="0.01" required inputmode="decimal"')}</div>${a.use==='Rental'?formInput('Current gross annual rent (₹ cr)','rent','number','min="0" step="0.001" required inputmode="decimal"')+'<div class="form-row">'+formInput('Occupancy (%)','occupancy','number','min="0" max="100" step="0.1" required inputmode="decimal"')+formInput('Lease remaining (months)','lease','number','min="0" max="1200" step="1" required inputmode="numeric"')+'</div>':'<p class="form-note">Rental income is set to zero for non-rental assets.</p>'}`:`${wizardSelect('Execution status','stage',['Completed','Under construction','Stalled','Land'])}${wizardSelect('Documentation status','docs',['Reviewed / clear','Review pending','Unresolved issue'])}${formInput('Estimated time to sell (months)','exit','number','min="0" max="1200" step="1" required inputmode="numeric"')}<div class="notice">${esc(a.name)} · ${esc(a.city)}<br>Value ${money(+a.value)} · Debt ${money(+a.debt)}</div>`;openDialog(wizard.i<0?'Add holding':'Edit holding',`<div class="wizard-steps">${['Property','Financials','Risk inputs'].map((t,i)=>`<span class="${i<=s?'active':''}">${i+1}. ${t}</span>`).join('')}</div><form class="form" id="holding-form">${fields}<div class="form-error" id="wizard-error" role="alert"></div><div class="dialog-actions">${s?'<button type="button" class="btn light" data-action="wizard-back">Back</button>':''}<button type="submit" class="btn">${s===2?'Save holding':'Continue'}</button></div>${wizard.i>=0&&s===0?'<button class="text-button danger-text" type="button" data-action="remove-holding">Remove holding</button>':''}</form>`,'MY PORTFOLIO · '+(s+1)+' OF 3')}
function captureWizard(form){const a=wizard.asset;for(const [k,v] of new FormData(form)){a[k]=['value','debt','rent','occupancy','lease','exit'].includes(k)?Number(v):v.trim()}if(a.use!=='Rental'){a.rent=0;a.lease=0;a.occupancy=0}return a}
function confirmation(title,text,action){openDialog(title,`<p class="dialog-subtitle">${esc(text)}</p><div class="dialog-actions"><button class="btn light" data-action="close">Keep</button><button class="btn danger" data-action="${action}">Confirm</button></div>`,'CONFIRM')}
function resetFilters(){Object.assign(ui,{query:'',city:'',ticket:'',status:'',cat:-1,sort:'default',visibleDeals:3})}
function generateRisk(){const error=window.HCPortfolio.generate();if(error){toast(error);ui.portfolioTab='holdings'}else ui.portfolioTab='risk';render()}
document.addEventListener('click',ev=>{const el=ev.target.closest('button,a[data-action]');if(!el)return;const d=el.dataset;
 if(d.layout){ui.layout=d.layout;render();return}if(d.detail){detail(d.detail);return}if(d.save){saved.has(d.save)?saved.delete(d.save):saved.add(d.save);persist();render();return}if(d.cat!==undefined){ui.cat=+d.cat;ui.visibleDeals=3;render();return}if(d.opView){ui.opView=d.opView;ui.visibleDeals=3;render();return}if(d.clearFilter){ui[d.clearFilter]='';ui.visibleDeals=3;render();return}if(d.enquiry){enquiryForm(d.enquiry);return}if(d.brief){brief(d.brief);return}if(d.service){serviceForm(d.service);return}if(d.request){requestDetail(d.request);return}if(d.downloadRequest){downloadRequest(d.downloadRequest);return}if(d.requestFilter){ui.requestFilter=d.requestFilter;render();return}if(d.toggleRequest){const r=requests.find(r=>r.id===d.toggleRequest);r.status=r.status==='Cancelled'?'In progress':'Cancelled';persist();render();requestDetail(r.id);return}if(d.portfolioTab){ui.portfolioTab=d.portfolioTab;render();return}if(d.editHolding!==undefined){startWizard(+d.editHolding);return}
 switch(d.action){case'show-more-deals':{const prior=ui.visibleDeals;ui.visibleDeals+=3;render();const next=$('#opportunity-results')?.querySelectorAll('[data-record]')[prior]?.querySelector('button[data-detail]');next?.focus({preventScroll:true});break;}case'show-fewer-deals':ui.visibleDeals=3;render();$('#opportunity-count')?.scrollIntoView({block:'center',behavior:'instant'});$('#opportunity-results button[data-detail]')?.focus({preventScroll:true});break;case'close':closeDialog();break;case'filters':filterDialog();break;case'reset-filters':resetFilters();render();break;case'reset-modal-filters':$('#filter-form').querySelectorAll('select').forEach(e=>e.value='');break;case'clear-compare':ui.compare.clear();render();break;case'compare':showComparison();break;case'mandate':mandateForm();break;case'new-service':serviceForm();break;case'export-deals':csv([['INDICATIVE TERMS — NOT AN OFFER'],['ID','Opportunity','Category','City','Minimum ticket INR cr','Key metric','Metric basis','Term months','Status'],...filteredDeals().map(d=>[d.id,d.name,categories[d.cat].name,d.city,d.ticket??'On request',d.metricText,d.metricLabel,d.tenure,d.status])],'HC-Saarthi-Opportunities.csv');toast('Filtered opportunities exported');break;case'export-services':csv([['SERVICE REQUESTS'],['ID','Service','Asset','City','Status','Notes','Created'],...requests.filter(r=>r.kind==='service').map(r=>[r.id,r.subject,r.asset,r.city,r.status,r.notes,r.created])],'HC-Saarthi-Service-Requests.csv');toast('Service drafts exported');break;case'add-holding':startWizard();break;case'generate-risk':generateRisk();break;case'sample-portfolio':window.HCPortfolio.demo();render();break;case'clear-portfolio':confirmation('Clear portfolio?','This clears all holdings. Download a report first if you need it.','confirm-clear');break;case'confirm-clear':window.HCPortfolio.clear();closeDialog();render();break;case'wizard-back':captureWizard($('#holding-form'));wizard.step--;drawWizard();break;case'remove-holding':{const i=wizard.i;confirmation('Remove holding?',window.HCPortfolio.get().assets[i].name,'confirm-remove');$('#modal').dataset.removeIndex=i;break}case'confirm-remove':window.HCPortfolio.remove(+$('#modal').dataset.removeIndex);closeDialog();render();toast('Holding removed');break;}
});
document.addEventListener('change',ev=>{const e=ev.target;if(e.dataset.compare){if(e.checked){if(ui.compare.size>=3){e.checked=false;toast('Select up to three opportunities');return}ui.compare.add(e.dataset.compare)}else ui.compare.delete(e.dataset.compare);compareTray();return}const m={'city-filter':'city','ticket-filter':'ticket','status-filter':'status','deal-sort':'sort','report-city':'reportCity'};if(m[e.id]){ui[m[e.id]]=e.value;ui.visibleDeals=3;render()}});
document.addEventListener('input',ev=>{const e=ev.target,m={'deal-search':'query','research-search':'researchQuery','service-search':'serviceQuery'};if(m[e.id]){ui[m[e.id]]=e.value;ui.visibleDeals=3;render()}if(e.id==='portfolio-name'){window.HCPortfolio.get().name=e.value;window.HCPortfolio.get().dirty=true;window.HCPortfolio.get().sample=false}});
document.addEventListener('change',e=>{if(e.target.id!=='e35-service-select')return;const select=document.getElementById('e35-service-subtype');if(!select)return;const items=serviceSubtypes[e.target.value]||[];select.disabled=!items.length;select.innerHTML=options(items,'','Select the type of assistance');});
document.addEventListener('submit',ev=>{const f=ev.target;if(!['filter-form','enquiry-form','service-form','mandate-form','update-request-form','holding-form'].includes(f.id))return;ev.preventDefault();if(!f.reportValidity())return;const v=Object.fromEntries(new FormData(f));for(const k in v)if(typeof v[k]==='string')v[k]=v[k].trim();if(f.id==='filter-form'){Object.assign(ui,v,{visibleDeals:3});closeDialog();render()}else if(f.id==='enquiry-form'){const d=deals.find(d=>d.id===f.dataset.id);addRequest({kind:'enquiry',subject:d.name,deal:d.id,city:d.city,amount:v.amount,notes:v.notes})}else if(f.id==='service-form'){if(!v.service||!v.subtype||!v.asset||!v.city){toast('Choose a service, subtype and asset.');return}addRequest({kind:'service',subject:v.service,notes:v.notes||'',...v})}else if(f.id==='mandate-form'){if(!v.asset||!v.city||!v.notes){toast('Complete the asset, city and details.');return}addRequest({kind:'mandate',subject:v.mandate,...v})}else if(f.id==='update-request-form'){const r=requests.find(r=>r.id===f.dataset.id);r.notes=v.notes;if(['In progress','Completed'].includes(v.status))r.status=v.status;persist();render();toast('Request updated');closeDialog()}else if(f.id==='holding-form'){const a=captureWizard(f);if(!a.name||!a.city){$('#wizard-error').textContent='Enter an asset name and city.';return}if(wizard.step<2){wizard.step++;drawWizard()}else{window.HCPortfolio.saveAsset(wizard.i,structuredClone(a));closeDialog();render();toast('Holding saved. Generate a new report to update the analysis.')}}});
$('#close-modal').addEventListener('click',closeDialog);$('#modal').addEventListener('cancel',()=>{wizard=null});$('#modal').addEventListener('click',ev=>{if(ev.target===$('#modal')){const r=ev.target.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)closeDialog()}});
window.addEventListener('hashchange',()=>{closeDialog();render();window.scrollTo(0,0);$('#app').focus({preventScroll:true})});
window.Saarthi={ui,deals,categories,resources,reports,filteredDeals,getRequests:()=>requests,render};
window.render=render;
window.toast=toast;
